def moving_average(values, window):
    result = []
    total = 0.0
    for index, value in enumerate(values):
        total += value
        if index >= window:
            total -= values[index - window]
        count = min(index + 1, window)
        result.append(total / count)
    return result

def smoothed_series(samples, span):
    output = []
    running = 0.0
    for position, sample in enumerate(samples):
        running += sample
        if position >= span:
            running -= samples[position - span]
        divisor = min(position + 1, span)
        output.append(running / divisor)
    return output
